function n(t){return String(t||"").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")}function a(t,r=16){return String(t||"").split(",").map(e=>e.trim()).filter(Boolean).slice(0,r)}function i(t){if(!t)return"—";try{return new Date(t).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"})}catch{return"—"}}function o(t){if(!t)return"";try{return new Date(t).toLocaleString("pt-BR")}catch{return""}}function c(t){if(!t)return"Sem data";try{const e=new Date(t).toLocaleDateString("pt-BR",{month:"long",year:"numeric"});return e.charAt(0).toUpperCase()+e.slice(1)}catch{return"Sem data"}}export{i as a,o as b,c as f,n,a as p};
